-- GATE: G1 ZERO
SELECT a.ids_duplicados, a.fecha_mal_formato, a.particion_inconsistente, a.importe_invalido, a.lead_time_invalido, f.sin_proveedor, f.sin_producto, f.sin_categoria, f.sin_unidad, a.info_filas, a.info_lead_time_vacio, w.info_filas_web
FROM (SELECT count(*) - count(DISTINCT id_compra) AS ids_duplicados, count_if(NOT regexp_like(fecha, '^\d{4}-\d{2}-\d{2}$')) AS fecha_mal_formato, count_if(anio <> substr(fecha, 1, 4) OR mes <> substr(fecha, 6, 2)) AS particion_inconsistente, count_if(try_cast(cantidad AS double) IS NULL OR try_cast(precio_unitario AS double) IS NULL) AS importe_invalido, count_if(NULLIF(trim(lead_time_dias), '') IS NOT NULL AND try_cast(trim(lead_time_dias) AS integer) IS NULL) AS lead_time_invalido, count(*) AS info_filas, count_if(NULLIF(trim(lead_time_dias), '') IS NULL) AS info_lead_time_vacio FROM tmp_v_compras) a
CROSS JOIN (SELECT count_if(p.proveedor_id IS NULL) AS sin_proveedor, count_if(pr.producto_id IS NULL) AS sin_producto, count_if(c.categoria_id IS NULL) AS sin_categoria, count_if(u.unidad_organizacional_id IS NULL) AS sin_unidad FROM tmp_v_compras v LEFT JOIN tmp_a_proveedores p ON v.proveedor_id = p.proveedor_id LEFT JOIN tmp_a_productos pr ON v.producto_id = pr.producto_id LEFT JOIN tmp_a_categorias c ON v.categoria_id = c.categoria_id LEFT JOIN tmp_a_unidades_organizacionales u ON v.unidad_organizacional_id = u.unidad_organizacional_id) f
CROSS JOIN (SELECT count(*) AS info_filas_web FROM tmp_csv_compras_web) w;
